    "signals",
    "filters",
    "machineTypes",
    "machines",
    "processes",
    "peripherals",
    "missing",
    "resources",
    "runtime",
    "deliveries",
    "workers",
}

local KEY_FIELDS = {
    containers = { "name" },
    signals = { "name" },
    filters = { "name" },
    machineTypes = { "name" },
    machines = { "name" },
    processes = { "name" },
    peripherals = { "kind", "name" },
    missing = { "kind", "name" },
    resources = { "kind", "name" },
    runtime = { "name" },
    deliveries = { "id" },
