            end
        end
    end
end



function Protocol:onEvent(event, param1, param2)
    if event == "websocket_success" and param1 == self.url then
        self:onSocketOpened(param2)
        return true
    end
    if event == "websocket_message" and param1 == self.url then
        self:handleMessage(param2)
