Store.containerKindList = { "item", "fluid" }
Store.sideList = { "top", "bottom", "left", "right", "front", "back" }
Store.opList = { "gt", "ge", "eq", "le", "lt" }

local KNOWN_RULE_TYPES = {
    item_include = true,
    item_exclude = true,
    fluid_include = true,
    fluid_exclude = true,
    itemTag_include = true,
    itemTag_exclude = true,
    fluidTag_include = true,
    fluidTag_exclude = true,
    filter_include = true,
    filter_exclude = true,
}

local function isName(s)
    return type(s) == "string" and s:match("%S") ~= nil
end

local function normalizeSides(list)
    local out = {}
    for _, side in ipairs(list or {}) do
        if VALID_SIDES[side] then
            out[#out + 1] = side
        end
    end

    if #out == 0 then
        return { "top", "bottom", "left", "right", "front", "back" }
    end
    return out
end

local function normalizeStringList(list)
    local out = {}
    for _, v in ipairs(list or {}) do
        if type(v) == "string" and v ~= "" then
            out[#out + 1] = v
        end
    end
    return out
end




function Store.containerKey(containerKind, name)
    return (containerKind == "fluid" and "fluid:" or "item:") .. tostring(name or "")
end


function Store.containerPlainName(value)
    local text = tostring(value or "")
    local prefix, rest = text:match("^(%a+):(.*)$")
    if prefix == "item" or prefix == "fluid" then
        return rest
    end
    return text
end

function Store.emptyData()
    return {
        version = 1,
        containers = {},
        signals = {},
        filters = {},
        machineTypes = {},
        machines = {},
        processes = {},
        settings = {},
    }
end


function Store:scanSettings()
    local saved = self:get("settings", Store.SETTINGS_NAME) or {}
    local defaults = Store.SCAN_DEFAULTS
    local function pick(value, fallback)
        local number = tonumber(value)
        if not number then
            return fallback
        end
        local limits = Store.SCAN_LIMITS
        return math.max(limits.min, math.min(limits.max, math.floor(number)))
    end
    return {
        storageScanMs = pick(saved.storageScanMs, defaults.storageScanMs),
        inputScanMs = pick(saved.inputScanMs, defaults.inputScanMs),
