                        obj.name = plain
                        self.data.containers[Store.containerKey(containerKind, plain)] =
                            self:normalize("containers", plain, obj)
                    else
                        obj.name = obj.name or key
                        self.data[kind][key] = self:normalize(kind, key, obj)
                    end
                end
            end
        end
    end
    return true
end


function Store:getRoom()
