                return false, label .. "\\u5143\\u7D20 " .. index .. " \\u7684\\u69FD\\u4F4D\\u4E0D\\u80FD\\u5C0F\\u4E8E -1"
            end
        end
        return true
    elseif kind == "placeholder" then
