            { obj.fluidInputs, "\\u6D41\\u4F53\\u8F93\\u5165\\u5BB9\\u5668", "fluid" },
            { obj.itemOutputs, "\\u7269\\u54C1\\u8F93\\u51FA\\u5BB9\\u5668", "item" },
